mapper.select:
SELECT X.BUYER ,X.BUYER_NAME ,X.REVISION ,X.STATUS ,X.IRS_NO ,X.KEP_USER_DEPT ,X.KEP_USER_DEPT_NM ,X.KEP_USER_ID ,X.KEP_USER_NM ,X.ADD_USER_ID ,X.ADD_USER_NM ,X.ADD_DATE ,X.CHANGE_USER_ID ,X.CHANGE_USER_NM ,X.CHANGE_DATE ,X.PROCESS_TYPE ,X.STATUS_NM ,X.PROCESS_TYPE_1 ,X.PROCESS_TYPE_2 ,X.PROCESS_TYPE_3 ,X.PROCESS_TYPE_4 ,X.PROCESS_TYPE_5 ,X.CUSTOMER_MNG_YN ,X.VISIT_DATE ,X.ADD_USER_DEPT ,X.ADD_USER_DEPT_NM FROM ( /* selectMasterMdCtNewCustomerManageList */ SELECT A.BUYER ,A.BUYER_NAME ,B.REVISION ,A.STATUS ,A.IRS_NO ,A.KEP_USER_DEPT ,( SELECT COD.TEXT1 FROM ICOMCOD2 COD WHERE COD.TYPE = 'C001' AND COD.COMPANY_CODE = 'KRKORE0001' AND COD.CODE = A.KEP_USER_DEPT) AS KEP_USER_DEPT_NM ,A.KEP_USER_ID ,(SELECT USR.USER_NAME_LOC FROM ICOMLUSR USR WHERE USR.USER_ID = A.KEP_USER_ID) AS KEP_USER_NM ,A.ADD_USER_ID ,C.DEPARTMENT AS ADD_USER_DEPT ,( SELECT COD.TEXT1 FROM ICOMCOD2 COD WHERE COD.TYPE = 'C001' AND COD.COMPANY_CODE = 'KRKORE0001' AND COD.CODE = C.DEPARTMENT) AS ADD_USER_DEPT_NM ,(SELECT USR.USER_NAME_LOC FROM ICOMLUSR USR WHERE USR.USER_ID = A.ADD_USER_ID) AS ADD_USER_NM ,A.ADD_DATE ,A.CHANGE_USER_ID ,(SELECT USR.USER_NAME_LOC FROM ICOMLUSR USR WHERE USR.USER_ID = A.CHANGE_USER_ID) AS CHANGE_USER_NM ,A.CHANGE_DATE ,B.PROCESS_TYPE ,DECODE(A.BUYER_CLOSE_FLAG,'Y','종결',DECODE(B.PROCESS_TYPE,'CP','완료','진행')) AS STATUS_NM ,DECODE(B.PROCESS_TYPE,'GA','/resources/images/icon_g_50.gif', '/resources/images/icon_bl_50.gif') AS PROCESS_TYPE_1 ,DECODE(B.PROCESS_TYPE,'GA','', 'BI','/resources/images/icon_g_50.gif','/resources/images/icon_bl_50.gif') AS PROCESS_TYPE_2 ,DECODE(B.PROCESS_TYPE,'GA','', 'BI','', 'BD','/resources/images/icon_g_50.gif','/resources/images/icon_bl_50.gif') AS PROCESS_TYPE_3 ,DECODE(B.PROCESS_TYPE,'GA','', 'BI','', 'BD','', 'ST', '/resources/images/icon_g_50.gif','/resources/images/icon_bl_50.gif') AS PROCESS_TYPE_4 ,DECODE(B.PROCESS_TYPE,'GA','', 'BI','', 'BD','','ST', '','CN','/resources/images/icon_g_50.gif','/resources/images/icon_bl_50.gif') AS PROCESS_TYPE_5 ,F_GET_KEP_CUSTOMER_MNG(#{st_user_id}) AS CUSTOMER_MNG_YN ,(SELECT MAX(C.VISIT_DATE) FROM KEP_VISITDT C WHERE C.BUYER = A.BUYER AND C.STATUS <> 'D') AS VISIT_DATE FROM KEP_CUSTOMER A, KEP_CUSTOMER_RFQ B, ICOMLUSR C WHERE A.BUYER = B.BUYER AND A.STATUS != 'D' AND A.ADD_USER_ID = C.USER_ID AND B.STATUS IN ('C','R')
AND A.BUYER_NAME LIKE '%'||#{st_buyer} || '%'
AND REPLACE(A.IRS_NO,'-','') LIKE REPLACE(#{st_irs_no},'-','') || '%'
AND A.BUYER_CLOSE_FLAG = 'Y'
AND A.BUYER_CLOSE_FLAG = 'N' AND B.PROCESS_TYPE != 'CP'
AND B.PROCESS_TYPE = 'CP'
AND B.PROCESS_TYPE = #{st_process_type}
AND A.KEP_USER_ID = #{st_add_user_id}
AND (SELECT USER_NAME_LOC FROM ICOMLUSR WHERE USER_ID = A.KEP_USER_ID) LIKE '%'||#{st_add_user_name} || '%'
) X WHERE 1=1
AND X.ADD_USER_DEPT IN ('118', '134', '139')
AND X.ADD_USER_DEPT IN ('041', '152')
AND DECODE(X.CUSTOMER_MNG_YN,'Y','1', X.ADD_USER_DEPT) = DECODE(X.CUSTOMER_MNG_YN,'Y','1', #{st_dept_cd})
AND X.VISIT_DATE BETWEEN #{st_from_date} AND #{st_to_date}
AND TO_CHAR(TO_DATE(X.ADD_DATE),'YYYYMMDD') BETWEEN #{st_from_date} AND #{st_to_date}
ORDER BY X.BUYER

mapper.update:

