/* insertMasterMdCtNewCustomerManageList */
INSERT INTO BNTBUYERGROUP					
(
	CORP_CODE
	,CORP_NAME 	
	,GROUP_CODE
	,GROUP_NAME
	,GROUP_FLAG
	,USE_FLAG
	,ADD_USER_ID
	,ADD_DATE
) VALUES (									
	#{CORP_CODE}
	,#{CORP_NAME}
	,#{GROUP_CODE}
	,#{GROUP_NAME}
	,'B'
	,#{USE_FLAG}
	,#{st_user_id}
	,TO_CHAR(SYSDATE, 'YYYY/MM/DD')
)


		     /*updateMasterMdCtNewCustomer*/
                   UPDATE KEP_CUSTOMER
                   SET  BUYER_NAME = #{st_buyer_name}
                     , GROUP_NAME =#{st_group}
                     , STATUS = 'R'
                     , SALES_YEAR =#{st_sy_year}
                     , SALES_AMT =#{st_sy_amt}
                     , CREDIT_DATE =#{st_cd_year}
                     , CREDIT_RATING = #{st_cd_rank}
                     , IRS_NO = #{st_irs_no}
                     , CEO_NAME_LOC =#{st_ceo}
                     , INDUSTRY_TYPE =#{st_ind_type}
                     , MAJOR_ITEM =#{st_mi}
                     , EMPLOYEE_YEAR =#{st_epl_year}
                     , EMPLOYEE_CNT =#{st_epl}                     
                     , FACTORY_ADDRESS_LOC =#{st_fact_addr}
                     , KEP_USER_DEPT =#{st_kep_dept_cd}
                     , KEP_USER_ID =#{st_kep_user_id}
                     , BUSINESS_METHOD =#{st_process_type}
                     , MRO_YN =#{st_mro_yn}
                     , MRO_COMPANY =#{st_mro_cmpy}
                     , MRO_START =#{st_mro_s_date}
                     , MRO_END =#{st_mro_e_date}
                     , PAST_MRO_YN =#{st_past_mro_yn}
                     , PAST_MRO_COMPANY =#{st_past_mro_cmpy}
                     , PAST_MRO_START =#{st_past_mro_date}
                     , PAST_MRO_END =#{st_past_mro_e_date}
                     , MRO_YEAR_AMT =#{st_year_mro_amt}
                     , BILL_TYPE = #{st_bill_type}
                     , SYSTEM_TYPE =#{st_sys_type}
                     , MRO_SPEND = #{st_mro_spd}
                     , KEYMAN_DEPT_NAME1 =#{st_key_dept}
                     , KEYMAN_USER_NAME1 =#{st_key_nm}
                     , KEYMAN_TEL_NAME1 =#{st_key_tel}
                     , KEYMAN_DEPT_NAME2 =#{st_key_dept2}
                     , KEYMAN_USER_NAME2 =#{st_key_nm2}
                     , KEYMAN_TEL_NAME2 =#{st_key_tel2}
                     , KEYMAN_DEPT_NAME3 =#{st_key_dept3}
                     , KEYMAN_USER_NAME3 =#{st_key_nm3}
                     , KEYMAN_TEL_NAME3 =#{st_key_tel3}
                     , INTEREST_STATUS =#{st_int_status}
                     , INTEREST_USER =#{st_int_status_user}
                     , INTEREST_MAIN =#{st_int_main}
                     , TEL_NO = #{st_tel_no}
