                     , INDUSTRY_NM = #{st_industry}
                     , CHANGE_USER_ID =#{USER_ID}
                     , CHANGE_DATE =SYSDATE           
                 WHERE BUYER =#{st_com_code}


		     /*endMasterMdCtNewCustomer*/
                   UPDATE KEP_CUSTOMER
                   SET  BUYER_CLOSE_FLAG = #{st_buyer_close_flag_in}
