/* checkMasterMdCtNewCustomer */
SELECT	DECODE(COUNT(A.IRS_NO),0,'N','Y') AS RESULT_YN
FROM	KEP_CUSTOMER A
WHERE	1=1
AND		A.IRS_NO = #{st_irs_no}
AND		A.STATUS != 'D'
AND		A.KEP_USER_DEPT = #{USER_DEPT}
